// Filter applies the ModelWhereInput filter on the ModelQuery builder.
func (i *ModelWhereInput) Filter(q *ModelQuery) (*ModelQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyModelWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

